// @vitest-environment node
import { readFileSync } from 'node:fs';
import { beforeAll, describe, expect, it, vi } from 'vitest';

const WASM_DIR = new URL('../wasm-pkg/', import.meta.url);

vi.mock('./wasm', async () => {
    const { readFileSync: read } = await import('node:fs');
    const dir = new URL('../wasm-pkg/', import.meta.url);
    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
    // @ts-ignore — generated by scripts/build-wasm.sh (wasm-bindgen)
    const glue = await import('../wasm-pkg/anonymiser_wasm');
    glue.initSync({ module: read(new URL('anonymiser_wasm_bg.wasm', dir)) });
    return {
        ...glue,
        ensureWasm: async () => {},
        generate_salt: () => Uint8Array.from({ length: 32 }, (_, i) => i),
    };
});

import { anonymizeData } from './anonymize';
import { suppressForRelease } from './anonymity';
import { generateFile } from './generate';
import { parseTextInMemory } from './parse-text';
import { endSession, startSession } from './session';
import { streamAnonymize } from './stream';
import { STREAM_CHUNK_ROWS, STREAM_SLICE_BYTES } from '../lib/constants';
import { filterRows } from '../lib/pipeline-common';
import type { ParsedDataset } from '../lib/pipeline-common';
import { tableFormatOf } from '../lib/table-format';
import type { TextTableFormat } from '../lib/table/codec';
import type { AnonymizeOpts, ColumnPolicy, TokenEncoding } from '../types/policy';

const fixture = (name: string): Buffer => readFileSync(new URL(`../../../fixtures/parity/${name}`, import.meta.url));
const policyDoc = JSON.parse(fixture('policy.json').toString()) as {
    columns: { name: string; action: ColumnPolicy['type'] }[];
};
const policiesFor = (headers: string[]): Record<number, ColumnPolicy> =>
    Object.fromEntries(
        policyDoc.columns.map((c) => [headers.indexOf(c.name), { type: c.action } as ColumnPolicy])
    );
const noop = () => {};

const CASES: [string, TokenEncoding][] = [
    ['people.csv', 'hex'],
    ['people.tsv', 'base32'],
    ['people.jsonl', 'hex'],
];

beforeAll(() => {
    expect(() => readFileSync(new URL('anonymiser_wasm_bg.wasm', WASM_DIR))).not.toThrow();
});

describe.each(CASES)('CLI parity: %s (%s tokens)', (name, tokenEncoding) => {
    const format = tableFormatOf(name) as TextTableFormat;
    const opts: AnonymizeOpts = { dataset: 'parity', tokenEncoding };
    const expected = fixture(name.replace('people.', 'people.expected.')).toString('utf8');

    it('in-memory path (parse -> anonymise -> generate) is byte-identical to the CLI', async () => {
        endSession();
        await startSession('parity-passphrase');
        const parsed = await parseTextInMemory(new File([fixture(name).toString("utf8")], name), format, noop);
        const { data } = await anonymizeData(
            parsed.data, parsed.headers, parsed.metadata, policiesFor(parsed.headers), noop, opts
        );
        const blob = await generateFile(parsed.headers, data, format);
        expect(await blob.text()).toBe(expected);
    });

    it('streaming path is byte-identical to the CLI', async () => {
        endSession();
        await startSession('parity-passphrase');
        const file = new File([fixture(name).toString("utf8")], name);
        const headers = (await parseTextInMemory(file, format, noop)).headers;
        const res = await streamAnonymize(file, policiesFor(headers), opts, null, noop);
        expect(await res.blob!.text()).toBe(expected);
    });
});

describe('real keyed hashing across slices and chunks', () => {
    it('a multi-slice, multi-chunk stream equals the in-memory run (same tokens for same values)', async () => {
        endSession();
        await startSession('parity-passphrase');
        const lines = ['id,name,email'];
        for (let i = 0; i < 70_000; i++) lines.push(`${i},Person ${i % 997},p${i % 1301}@example.org`);
        const file = new File([lines.join('\n') + '\n'], 'many.csv');
        expect(file.size).toBeGreaterThan(STREAM_SLICE_BYTES + 1);
        const policies: Record<number, ColumnPolicy> = { 1: { type: 'hash' }, 2: { type: 'hash' } };

        const parsed = await parseTextInMemory(file, 'csv', noop);
        const mem = await anonymizeData(parsed.data, parsed.headers, [], policies, noop, { dataset: 'd' });
        const inMemory = await (await generateFile(parsed.headers, mem.data, 'csv')).text();

        const chunks: number[] = [];
        const streamed = await streamAnonymize(file, policies, { dataset: 'd' }, null, noop, (n) => chunks.push(n));
        expect(await streamed.blob!.text()).toBe(inMemory);
        expect(Math.max(...chunks)).toBeLessThanOrEqual(STREAM_CHUNK_ROWS);
        expect(chunks.length).toBeGreaterThan(10);
        expect(streamed.counts).toEqual(mem.counts);
    });
});

describe.each([
    ['cells', 'anonymity.expected.cells.csv', 'anonymity.expected.excluded-cells.csv'],
    ['rows', 'anonymity.expected.rows.csv', 'anonymity.expected.excluded-rows.csv'],
] as const)('CLI parity: k-anonymity suppression, %s mode', (mode, expectedName, expectedExcludedName) => {
    const anonPolicies = (headers: string[]): Record<number, ColumnPolicy> => {
        const doc = JSON.parse(fixture('anonymity-policy.json').toString()) as {
            columns: { name: string; action: ColumnPolicy['type'] }[];
        };
        return Object.fromEntries(
            doc.columns.map((c) => [
                headers.indexOf(c.name),
                (c.action === 'age-band'
                    ? { type: 'age-band', width: 10, referenceDate: '2026-01-01' }
                    : { type: c.action }) as ColumnPolicy,
            ])
        );
    };
    const run = async (excluded: ReadonlySet<number>): Promise<string> => {
        endSession();
        await startSession('parity-passphrase');
        const parsed = await parseTextInMemory(
            new File([fixture('anonymity.csv').toString('utf8')], 'anonymity.csv'), 'csv', noop
        );
        const kept = filterRows(parsed as unknown as ParsedDataset, excluded);
        const { data } = await anonymizeData(
            kept.data, kept.headers, kept.metadata, anonPolicies(kept.headers), noop,
            { dataset: 'parity', tokenEncoding: 'hex' }
        );
        const qi = ['dob', 'city'].map((n) => kept.headers.indexOf(n));
        const released = await suppressForRelease(data, kept.headers, qi, 2, mode);
        expect(released.check.passed).toBe(true);
        return await (await generateFile(kept.headers, released.data, 'csv')).text();
    };

    it('suppression after the policies is byte-identical to the CLI', async () => {
        expect(await run(new Set())).toBe(fixture(expectedName).toString('utf8'));
    });

    it('row exclusion before suppression is byte-identical to the CLI on the filtered input', async () => {
        expect(await run(new Set([1, 7]))).toBe(fixture(expectedExcludedName).toString('utf8'));
    });
});
